const prodBy = {};
prods.forEach(p => { prodBy[String(p.sku).trim()] = p; });
const custBy = {};
custs.forEach(c => { custBy[String(c.customer_id).trim()] = c; });
const savedAlready = {};
logs.forEach(l => { if (String(l.decision || '').trim() === 'rto_save_sent') { savedAlready[String(l.order_id || '').trim()] = true; } });
const rtoCost = num(cfg.rto_cost_inr) || 180;
const retShip = num(cfg.return_ship_cost_inr) || 120;
const minN = num(cfg.min_orders_for_signal) || 3;
const badPct = num(cfg.bad_rate_pct) || 30;
const TZ = num(cfg.tz_offset_minutes) || 330;
const pad = (n) => String(n).padStart(2, '0');
